import type { InvestorsPageContent } from '../types';
import { COMPANY, GRIEVANCE_OFFICER, KMP, KMP_CONTACT, REGISTRAR } from '@/lib/investors/contacts';
import { disclosures } from '@/lib/investors/disclosures';

/**
 * Seed and in-repo fallback for the Investors page (/investors): company facts, named contacts
 * (`contacts.ts`, transcribed from jetking.com/investors) and the disclosure lists
 * (`disclosures.json`, regenerated by `npm run sync:investors`).
 */
export const investorsDefaults: InvestorsPageContent = {
  id: 'investors',
  company: {
    registeredOffice: COMPANY.registeredOffice,
    phone: COMPANY.phone,
    email: COMPANY.email,
    listedAt: COMPANY.listedAt,
    scripCode: COMPANY.scripCode,
    tradingSymbol: COMPANY.tradingSymbol,
  },
  stockLive: disclosures.links.stockLive ?? '',
  latestNews: disclosures.links.latestNews ?? '',
  grievanceOfficer: { ...GRIEVANCE_OFFICER },
  registrar: { ...REGISTRAR },
  kmp: KMP.map((person) => ({ ...person, phone: KMP_CONTACT.phone, email: KMP_CONTACT.email })),
  syncedAt: disclosures.syncedAt,
  sections: disclosures.sections.map((s) => ({
    id: s.id,
    title: s.title,
    items: s.items.map((i) => ({ label: i.label, href: i.href })),
  })),
};
